/**
 * One-shot migration: scan every label/slug in the database for legacy
 * artefacts and translate them in-place.
 *
 * What's "legacy"?
 *   1. **Bad labels** — `label_ar === label_en` or one side is empty or both
 *      sides are in the same script. The pre-2026-05-10 stub copied input as-is
 *      to the other language slot, leaving thousands of records with the
 *      wrong-language text in label_ar (or label_en).
 *   2. **Placeholder slugs** — field.name or option.value matching
 *      `^item_<base36>$`. These were generated by the old `slugify` for any
 *      Arabic input. They still work as identifiers but read as gibberish in
 *      tooling, exports, and SQL.
 *
 * Migration order matters:
 *   - Field SLUG renames go through `renameField` which also updates
 *     records, formulas, lookup display fields, mirror target field names,
 *     section_mirror field-name lists, workflows, and views — atomically.
 *   - Field LABEL fixes piggyback on the same `renameField` call when the
 *     slug also changes (one round-trip instead of two).
 *   - Option VALUE renames walk every record in the parent model and
 *     rewrite single + multi-select stored values. There's no existing
 *     helper for this so this module owns it.
 *   - Frozen models: slug changes are SKIPPED (DDL would be required).
 *     Labels are still fixed. The user can request a SQL migration if they
 *     need a frozen field's slug renamed.
 *
 * Idempotency: running twice is a no-op — each candidate's predicate
 * stops matching after the first run.
 */

import type {
  AppModel,
  ModelSection,
  ModelField,
  FieldOption,
  FieldOptionGroup,
  SectionFieldGroup,
  ModelGroup,
  Workflow,
  Dashboard,
  Role,
  Profile,
  AppRecord,
} from '@/types';
import { translateLabel, type TranslationKind } from '@/lib/translateLabel';
import { needsTranslation } from '@/lib/autoTranslate';

const PLACEHOLDER_SLUG_RE = /^item_[a-z0-9]+$/;

export type CandidateKind =
  | 'model_label'
  | 'section_label'
  | 'field_label'
  | 'field_slug'
  | 'option_label'
  | 'option_value'
  | 'option_group_label'
  | 'section_field_group_label'
  | 'sidebar_group_label'
  | 'workflow_label'
  | 'dashboard_label'
  | 'widget_label'
  | 'role_label'
  | 'profile_label';

export interface MigrationCandidate {
  id: string;
  kind: CandidateKind;
  reason: 'bad_labels' | 'placeholder_slug';
  sourceText: string;
  /** Human path for previews — e.g. "Model: Clients › Section: Contact › Field: phone". */
  path: string;
  current: { label_ar?: string; label_en?: string; slug?: string };
  /** Filled in after translation runs, before apply. */
  proposed?: { label_ar: string; label_en: string; name: string };
  /** True if the candidate's owning model is frozen — slug renames are skipped. */
  isFrozen?: boolean;
  /** Internal pointers used by the apply step. Do not introspect from UI. */
  refs: {
    modelId?: string;
    sectionId?: string;
    fieldId?: string;
    optionId?: string;
    groupId?: string;
    workflowId?: string;
    dashboardId?: string;
    widgetId?: string;
    roleId?: string;
    profileId?: string;
  };
}

interface ScanInput {
  models: AppModel[];
  groups: ModelGroup[];
  workflows: Workflow[];
  dashboards: Dashboard[];
  roles: Role[];
  profiles: Profile[];
}

/**
 * Walk every entity in the store and return the list of items that need
 * migration. Returns an empty array if everything is already clean — a
 * cheap idempotency check.
 */
export function scanLegacyEntities(state: ScanInput): MigrationCandidate[] {
  const out: MigrationCandidate[] = [];

  for (const g of state.groups) {
    if (needsTranslation(g.label_ar, g.label_en)) {
      out.push({
        id: `sidebar_group:${g.id}`,
        kind: 'sidebar_group_label',
        reason: 'bad_labels',
        sourceText: g.label_ar || g.label_en,
        path: `Group: ${g.label_ar || g.label_en}`,
        current: { label_ar: g.label_ar, label_en: g.label_en },
        refs: { groupId: g.id },
      });
    }
  }

  for (const m of state.models) {
    const isFrozen = !!m.is_hardcoded;
    const modelDisplay = m.label_ar || m.label_en || m.name;

    if (needsTranslation(m.label_ar, m.label_en)) {
      out.push({
        id: `model:${m.id}`,
        kind: 'model_label',
        reason: 'bad_labels',
        sourceText: m.label_ar || m.label_en || m.name,
        path: `Model: ${modelDisplay}`,
        current: { label_ar: m.label_ar, label_en: m.label_en },
        isFrozen,
        refs: { modelId: m.id },
      });
    }

    for (const s of m.schema.sections) {
      const sectionDisplay = s.label_ar || s.label_en;
      if (needsTranslation(s.label_ar, s.label_en)) {
        out.push({
          id: `section:${m.id}:${s.id}`,
          kind: 'section_label',
          reason: 'bad_labels',
          sourceText: s.label_ar || s.label_en,
          path: `${modelDisplay} › Section: ${sectionDisplay}`,
          current: { label_ar: s.label_ar, label_en: s.label_en },
          isFrozen,
          refs: { modelId: m.id, sectionId: s.id },
        });
      }

      for (const fg of s.field_groups ?? []) {
        if (needsTranslation(fg.label_ar, fg.label_en)) {
          out.push({
            id: `section_field_group:${m.id}:${s.id}:${fg.id}`,
            kind: 'section_field_group_label',
            reason: 'bad_labels',
            sourceText: fg.label_ar || fg.label_en,
            path: `${modelDisplay} › ${sectionDisplay} › Group: ${fg.label_ar || fg.label_en}`,
            current: { label_ar: fg.label_ar, label_en: fg.label_en },
            isFrozen,
            refs: { modelId: m.id, sectionId: s.id, groupId: fg.id },
          });
        }
      }

      for (const f of s.fields) {
        const fieldDisplay = f.label_ar || f.label_en || f.name;
        const labelBad = needsTranslation(f.label_ar, f.label_en);
        const slugBad = PLACEHOLDER_SLUG_RE.test(f.name);

        // If both the slug and the labels are bad, push a single field_slug
        // candidate that fixes everything in one renameField call. Otherwise
        // push the individual issue.
        if (slugBad && !isFrozen) {
          out.push({
            id: `field_slug:${m.id}:${f.id}`,
            kind: 'field_slug',
            reason: 'placeholder_slug',
            sourceText: f.label_ar || f.label_en || f.name,
            path: `${modelDisplay} › ${sectionDisplay} › Field: ${fieldDisplay} (slug: ${f.name})`,
            current: { label_ar: f.label_ar, label_en: f.label_en, slug: f.name },
            isFrozen,
            refs: { modelId: m.id, sectionId: s.id, fieldId: f.id },
          });
        } else if (labelBad) {
          out.push({
            id: `field_label:${m.id}:${f.id}`,
            kind: 'field_label',
            reason: 'bad_labels',
            sourceText: f.label_ar || f.label_en || f.name,
            path: `${modelDisplay} › ${sectionDisplay} › Field: ${fieldDisplay}`,
            current: { label_ar: f.label_ar, label_en: f.label_en, slug: f.name },
            isFrozen,
            refs: { modelId: m.id, sectionId: s.id, fieldId: f.id },
          });
        }

        // Dropdown / multiselect / section_selector options.
        for (const opt of f.options ?? []) {
          // section_selector options whose value matches a section id are
          // managed automatically — leave them alone. Their value IS the
          // section UUID; the label tracks the section name.
          if (opt.is_section_option) continue;
          const optDisplay = opt.label_ar || opt.label_en || opt.value;
          const optLabelBad = needsTranslation(opt.label_ar, opt.label_en);
          const optValueBad = PLACEHOLDER_SLUG_RE.test(opt.value);

          if (optValueBad) {
            // Combined fix: translate the label AND rename value + rewrite records.
            out.push({
              id: `option_value:${m.id}:${f.id}:${opt.id}`,
              kind: 'option_value',
              reason: 'placeholder_slug',
              sourceText: opt.label_ar || opt.label_en || opt.value,
              path: `${modelDisplay} › ${sectionDisplay} › ${fieldDisplay} › Option: ${optDisplay} (value: ${opt.value})`,
              current: { label_ar: opt.label_ar, label_en: opt.label_en, slug: opt.value },
              isFrozen,
              refs: { modelId: m.id, sectionId: s.id, fieldId: f.id, optionId: opt.id },
            });
          } else if (optLabelBad) {
            out.push({
              id: `option_label:${m.id}:${f.id}:${opt.id}`,
              kind: 'option_label',
              reason: 'bad_labels',
              sourceText: opt.label_ar || opt.label_en || opt.value,
              path: `${modelDisplay} › ${sectionDisplay} › ${fieldDisplay} › Option: ${optDisplay}`,
              current: { label_ar: opt.label_ar, label_en: opt.label_en, slug: opt.value },
              isFrozen,
              refs: { modelId: m.id, sectionId: s.id, fieldId: f.id, optionId: opt.id },
            });
          }
        }

        for (const og of f.option_groups ?? []) {
          if (needsTranslation(og.label_ar, og.label_en)) {
            out.push({
              id: `option_group:${m.id}:${f.id}:${og.id}`,
              kind: 'option_group_label',
              reason: 'bad_labels',
              sourceText: og.label_ar || og.label_en,
              path: `${modelDisplay} › ${sectionDisplay} › ${fieldDisplay} › Option group: ${og.label_ar || og.label_en}`,
              current: { label_ar: og.label_ar, label_en: og.label_en },
              isFrozen,
              refs: { modelId: m.id, sectionId: s.id, fieldId: f.id, groupId: og.id },
            });
          }
        }
      }
    }
  }

  for (const w of state.workflows) {
    if (needsTranslation(w.label_ar, w.label_en)) {
      out.push({
        id: `workflow:${w.id}`,
        kind: 'workflow_label',
        reason: 'bad_labels',
        sourceText: w.label_ar || w.label_en,
        path: `Workflow: ${w.label_ar || w.label_en}`,
        current: { label_ar: w.label_ar, label_en: w.label_en },
        refs: { workflowId: w.id },
      });
    }
  }

  for (const d of state.dashboards) {
    if (needsTranslation(d.label_ar, d.label_en)) {
      out.push({
        id: `dashboard:${d.id}`,
        kind: 'dashboard_label',
        reason: 'bad_labels',
        sourceText: d.label_ar || d.label_en,
        path: `Dashboard: ${d.label_ar || d.label_en}`,
        current: { label_ar: d.label_ar, label_en: d.label_en },
        refs: { dashboardId: d.id },
      });
    }
    for (const widget of d.widgets ?? []) {
      const titleAr = widget.title_ar ?? '';
      const titleEn = widget.title_en ?? '';
      if (needsTranslation(titleAr, titleEn) && (titleAr || titleEn)) {
        out.push({
          id: `widget:${d.id}:${widget.id}`,
          kind: 'widget_label',
          reason: 'bad_labels',
          sourceText: titleAr || titleEn,
          path: `Dashboard ${d.label_ar || d.label_en} › Widget: ${titleAr || titleEn}`,
          current: { label_ar: titleAr, label_en: titleEn },
          refs: { dashboardId: d.id, widgetId: widget.id },
        });
      }
    }
  }

  for (const r of state.roles) {
    if (needsTranslation(r.label_ar, r.label_en)) {
      out.push({
        id: `role:${r.id}`,
        kind: 'role_label',
        reason: 'bad_labels',
        sourceText: r.label_ar || r.label_en,
        path: `Role: ${r.label_ar || r.label_en}`,
        current: { label_ar: r.label_ar, label_en: r.label_en },
        refs: { roleId: r.id },
      });
    }
  }

  for (const p of state.profiles) {
    if (needsTranslation(p.label_ar, p.label_en)) {
      out.push({
        id: `profile:${p.id}`,
        kind: 'profile_label',
        reason: 'bad_labels',
        sourceText: p.label_ar || p.label_en,
        path: `Profile: ${p.label_ar || p.label_en}`,
        current: { label_ar: p.label_ar, label_en: p.label_en },
        refs: { profileId: p.id },
      });
    }
  }

  return out;
}

const KIND_TO_TRANSLATION_KIND: Record<CandidateKind, TranslationKind> = {
  model_label: 'model',
  section_label: 'section',
  field_label: 'field',
  field_slug: 'field',
  option_label: 'option',
  option_value: 'option',
  option_group_label: 'group',
  section_field_group_label: 'group',
  sidebar_group_label: 'group',
  workflow_label: 'workflow',
  dashboard_label: 'dashboard',
  widget_label: 'dashboard',
  role_label: 'role',
  profile_label: 'profile',
};

/**
 * Resolve a candidate's translation. Stores the result onto `c.proposed`
 * for the apply step to read. Throws on translation failure — caller
 * decides whether to skip or abort.
 */
export async function translateCandidate(c: MigrationCandidate): Promise<void> {
  const kind = KIND_TO_TRANSLATION_KIND[c.kind];
  const out = await translateLabel(c.sourceText, kind);
  c.proposed = out;
}

interface ApplyDeps {
  // Live store snapshot — mutated through these.
  getState: () => {
    models: AppModel[];
    groups: ModelGroup[];
    workflows: Workflow[];
    dashboards: Dashboard[];
    roles: Role[];
    profiles: Profile[];
    records: Record<string, AppRecord[]>;
  };
  saveModel: (model: AppModel) => void;
  saveGroup: (group: ModelGroup) => void;
  saveWorkflow: (workflow: Workflow) => void;
  saveDashboard: (dashboard: Dashboard) => void;
  saveRole: (role: Role) => void;
  saveProfile: (profile: Profile) => void;
  saveRecord: (record: AppRecord) => Promise<unknown> | void;
  renameField: (modelId: string, fieldId: string, updatedField: ModelField) => void;
}

/**
 * Persist a single migrated candidate. Throws if the underlying entity
 * was deleted between scan and apply (treats it as a skip — caller logs).
 */
export async function applyCandidate(
  c: MigrationCandidate,
  deps: ApplyDeps,
): Promise<void> {
  if (!c.proposed) throw new Error(`candidate ${c.id} has no translation`);
  const { proposed } = c;
  const state = deps.getState();

  switch (c.kind) {
    case 'sidebar_group_label': {
      const g = state.groups.find((x) => x.id === c.refs.groupId);
      if (!g) throw new Error('group disappeared');
      deps.saveGroup({ ...g, label_ar: proposed.label_ar, label_en: proposed.label_en });
      return;
    }

    case 'model_label': {
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      deps.saveModel({
        ...m,
        label_ar: proposed.label_ar,
        label_en: proposed.label_en,
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'section_label': {
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      deps.saveModel({
        ...m,
        schema: {
          ...m.schema,
          sections: m.schema.sections.map((s) =>
            s.id === c.refs.sectionId
              ? { ...s, label_ar: proposed.label_ar, label_en: proposed.label_en }
              : s,
          ),
        },
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'section_field_group_label': {
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      deps.saveModel({
        ...m,
        schema: {
          ...m.schema,
          sections: m.schema.sections.map((s) => {
            if (s.id !== c.refs.sectionId) return s;
            return {
              ...s,
              field_groups: (s.field_groups ?? []).map((fg) =>
                fg.id === c.refs.groupId
                  ? { ...fg, label_ar: proposed.label_ar, label_en: proposed.label_en }
                  : fg,
              ),
            };
          }),
        },
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'field_label': {
      // Label-only update. Don't touch slug or any other field property.
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      deps.saveModel({
        ...m,
        schema: {
          ...m.schema,
          sections: m.schema.sections.map((s) => {
            if (s.id !== c.refs.sectionId) return s;
            return {
              ...s,
              fields: s.fields.map((f) =>
                f.id === c.refs.fieldId
                  ? { ...f, label_ar: proposed.label_ar, label_en: proposed.label_en }
                  : f,
              ),
            };
          }),
        },
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'field_slug': {
      // Slug rename — propagates to records, formulas, lookups, mirrors,
      // section_mirrors, workflows, views via applyFieldRename inside the
      // store action.
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      const f = m.schema.sections.flatMap((s) => s.fields).find((x) => x.id === c.refs.fieldId);
      if (!f) throw new Error('field disappeared');
      if (m.is_hardcoded) {
        // Defensive — scanner already filters this out, but keep the rail.
        throw new Error('frozen model — field slug rename requires a SQL migration');
      }
      const updatedField: ModelField = {
        ...f,
        name: proposed.name,
        label_ar: proposed.label_ar,
        label_en: proposed.label_en,
      };
      deps.renameField(m.id, f.id, updatedField);
      return;
    }

    case 'option_label': {
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      deps.saveModel({
        ...m,
        schema: {
          ...m.schema,
          sections: m.schema.sections.map((s) => {
            if (s.id !== c.refs.sectionId) return s;
            return {
              ...s,
              fields: s.fields.map((f) => {
                if (f.id !== c.refs.fieldId) return f;
                return {
                  ...f,
                  options: (f.options ?? []).map((o) =>
                    o.id === c.refs.optionId
                      ? { ...o, label_ar: proposed.label_ar, label_en: proposed.label_en }
                      : o,
                  ),
                };
              }),
            };
          }),
        },
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'option_value': {
      // Rename the option value AND rewrite every record that referenced
      // the old value. This is the option-equivalent of `renameField`.
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      const sec = m.schema.sections.find((s) => s.id === c.refs.sectionId);
      if (!sec) throw new Error('section disappeared');
      const fld = sec.fields.find((x) => x.id === c.refs.fieldId);
      if (!fld) throw new Error('field disappeared');
      const opt = (fld.options ?? []).find((o) => o.id === c.refs.optionId);
      if (!opt) throw new Error('option disappeared');
      const oldValue = opt.value;
      const newValue = proposed.name;
      if (oldValue === newValue) {
        // Translation produced the same slug — skip the record walk and
        // just patch the labels.
        deps.saveModel({
          ...m,
          schema: {
            ...m.schema,
            sections: m.schema.sections.map((s) => s.id === sec.id ? {
              ...s,
              fields: s.fields.map((f) => f.id === fld.id ? {
                ...f,
                options: (f.options ?? []).map((o) => o.id === opt.id ? {
                  ...o,
                  label_ar: proposed.label_ar,
                  label_en: proposed.label_en,
                } : o),
              } : f),
            } : s),
          },
          updated_at: new Date().toISOString(),
        });
        return;
      }
      // Collision check: if another option in the SAME field already uses
      // newValue, append a counter so we don't merge two distinct options.
      const existingValues = new Set((fld.options ?? []).filter((o) => o.id !== opt.id).map((o) => o.value));
      let finalNewValue = newValue;
      let suffix = 2;
      while (existingValues.has(finalNewValue)) {
        finalNewValue = `${newValue}_${suffix}`;
        suffix += 1;
      }
      // Walk every record in this model and rewrite stored values.
      const fieldName = fld.name;
      const modelRecords = state.records[m.id] ?? [];
      const touched: AppRecord[] = [];
      for (const r of modelRecords) {
        const cur = r.data[fieldName];
        if (cur === oldValue) {
          touched.push({
            ...r,
            data: { ...r.data, [fieldName]: finalNewValue },
            updated_at: new Date().toISOString(),
          });
        } else if (Array.isArray(cur)) {
          let changed = false;
          const next = cur.map((v) => {
            if (v === oldValue) {
              changed = true;
              return finalNewValue;
            }
            return v;
          });
          if (changed) {
            touched.push({
              ...r,
              data: { ...r.data, [fieldName]: next },
              updated_at: new Date().toISOString(),
            });
          }
        }
      }
      // Persist the option metadata change first.
      deps.saveModel({
        ...m,
        schema: {
          ...m.schema,
          sections: m.schema.sections.map((s) => s.id === sec.id ? {
            ...s,
            fields: s.fields.map((f) => f.id === fld.id ? {
              ...f,
              options: (f.options ?? []).map((o) => o.id === opt.id ? {
                ...o,
                value: finalNewValue,
                label_ar: proposed.label_ar,
                label_en: proposed.label_en,
              } : o),
            } : f),
          } : s),
        },
        updated_at: new Date().toISOString(),
      });
      // Then save every touched record. saveRecord routes through the same
      // record_save RPC the live form uses, so frozen models work too.
      for (const r of touched) {
        await deps.saveRecord(r);
      }
      return;
    }

    case 'option_group_label': {
      const m = state.models.find((x) => x.id === c.refs.modelId);
      if (!m) throw new Error('model disappeared');
      deps.saveModel({
        ...m,
        schema: {
          ...m.schema,
          sections: m.schema.sections.map((s) => {
            if (s.id !== c.refs.sectionId) return s;
            return {
              ...s,
              fields: s.fields.map((f) => {
                if (f.id !== c.refs.fieldId) return f;
                return {
                  ...f,
                  option_groups: (f.option_groups ?? []).map((og) =>
                    og.id === c.refs.groupId
                      ? { ...og, label_ar: proposed.label_ar, label_en: proposed.label_en }
                      : og,
                  ),
                };
              }),
            };
          }),
        },
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'workflow_label': {
      const w = state.workflows.find((x) => x.id === c.refs.workflowId);
      if (!w) throw new Error('workflow disappeared');
      deps.saveWorkflow({
        ...w,
        label_ar: proposed.label_ar,
        label_en: proposed.label_en,
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'dashboard_label': {
      const d = state.dashboards.find((x) => x.id === c.refs.dashboardId);
      if (!d) throw new Error('dashboard disappeared');
      deps.saveDashboard({
        ...d,
        label_ar: proposed.label_ar,
        label_en: proposed.label_en,
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'widget_label': {
      const d = state.dashboards.find((x) => x.id === c.refs.dashboardId);
      if (!d) throw new Error('dashboard disappeared');
      deps.saveDashboard({
        ...d,
        widgets: (d.widgets ?? []).map((w) =>
          w.id === c.refs.widgetId
            ? { ...w, title_ar: proposed.label_ar, title_en: proposed.label_en }
            : w,
        ),
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'role_label': {
      const r = state.roles.find((x) => x.id === c.refs.roleId);
      if (!r) throw new Error('role disappeared');
      deps.saveRole({
        ...r,
        label_ar: proposed.label_ar,
        label_en: proposed.label_en,
        updated_at: new Date().toISOString(),
      });
      return;
    }

    case 'profile_label': {
      const p = state.profiles.find((x) => x.id === c.refs.profileId);
      if (!p) throw new Error('profile disappeared');
      deps.saveProfile({
        ...p,
        label_ar: proposed.label_ar,
        label_en: proposed.label_en,
        updated_at: new Date().toISOString(),
      });
      return;
    }
  }
}

export interface MigrationProgress {
  done: number;
  total: number;
  current?: MigrationCandidate;
  lastResult?: 'translated' | 'applied' | 'failed' | 'skipped';
  error?: string;
}

export interface MigrationOutcome {
  applied: MigrationCandidate[];
  skipped: { candidate: MigrationCandidate; reason: string }[];
  failed: { candidate: MigrationCandidate; error: string }[];
}

/**
 * Translate every candidate in `candidates`. Returns the list with
 * `proposed` filled in for those that translated successfully.
 *
 * Throttled: ~5 concurrent translation calls. Anthropic's free-tier
 * burst is forgiving but the cache makes most calls cheap anyway.
 */
export async function translateCandidates(
  candidates: MigrationCandidate[],
  onProgress?: (p: MigrationProgress) => void,
  abortSignal?: AbortSignal,
): Promise<{ ok: MigrationCandidate[]; failed: { candidate: MigrationCandidate; error: string }[] }> {
  const ok: MigrationCandidate[] = [];
  const failed: { candidate: MigrationCandidate; error: string }[] = [];
  let done = 0;
  const total = candidates.length;
  const concurrency = 5;
  let cursor = 0;

  async function worker() {
    while (true) {
      if (abortSignal?.aborted) return;
      const idx = cursor;
      cursor += 1;
      if (idx >= total) return;
      const c = candidates[idx]!;
      try {
        await translateCandidate(c);
        ok.push(c);
        done += 1;
        onProgress?.({ done, total, current: c, lastResult: 'translated' });
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        failed.push({ candidate: c, error: msg });
        done += 1;
        onProgress?.({ done, total, current: c, lastResult: 'failed', error: msg });
      }
    }
  }

  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  return { ok, failed };
}

/**
 * Apply translated candidates one at a time. Sequential — we don't want
 * concurrent saveModel calls racing on the same model row.
 */
export async function applyCandidates(
  candidates: MigrationCandidate[],
  deps: ApplyDeps,
  onProgress?: (p: MigrationProgress) => void,
  abortSignal?: AbortSignal,
): Promise<MigrationOutcome> {
  const applied: MigrationCandidate[] = [];
  const skipped: { candidate: MigrationCandidate; reason: string }[] = [];
  const failed: { candidate: MigrationCandidate; error: string }[] = [];
  const total = candidates.length;
  let done = 0;
  for (const c of candidates) {
    if (abortSignal?.aborted) {
      skipped.push({ candidate: c, reason: 'aborted' });
      continue;
    }
    if (!c.proposed) {
      skipped.push({ candidate: c, reason: 'no translation' });
      done += 1;
      continue;
    }
    try {
      await applyCandidate(c, deps);
      applied.push(c);
      done += 1;
      onProgress?.({ done, total, current: c, lastResult: 'applied' });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      failed.push({ candidate: c, error: msg });
      done += 1;
      onProgress?.({ done, total, current: c, lastResult: 'failed', error: msg });
    }
  }
  return { applied, skipped, failed };
}

// Re-export for the UI to label rows.
export { needsTranslation };

// Type re-exports so the UI can avoid pulling from `@/types` directly.
export type { ModelField, ModelSection, FieldOption, FieldOptionGroup, SectionFieldGroup };
